// Získání vstupu z AI Agent (který vrací data v poli output)
const input = $input.first().json.output || $input.first().json.body?.chatInput || "";

// Přidáme diagnostický log
console.log("Vstupní data:", JSON.stringify($input.first().json));
console.log("Extrahovaný vstup:", input);

// Přidáme extrakci z query parametru, pokud body.chatInput není k dispozici
const effectiveInput = input || $input.first().json?.query || "";

// Formát: "MB Tool; risk_comparison"
let companies = [];
let analysis_type = 'general';

// Zpracování vstupu s oddělovačem
const parts = effectiveInput.split(';');

if (parts.length >= 1) {
  companies = parts[0].split(',').map(c => c.trim()).filter(c => c.length > 0);
}

if (parts.length >= 2) {
  analysis_type = parts[1].trim().toLowerCase();
}

// Ověření validního typu analýzy
if (!['risk_comparison', 'common_suppliers', 'general'].includes(analysis_type)) {
  analysis_type = 'general';
}

// Log výsledných dat
console.log("Extrahované společnosti:", companies);
console.log("Extrahovaný typ analýzy:", analysis_type);

return {
  json: {
    companies: companies,
    company_count: companies.length,
    analysis_type: analysis_type,
    query: effectiveInput,
    company: companies[0] || "" // Přidáno pro kompatibilitu
  }
};

// combine_data_objects - oprava detekce vztahových dat
try {
  // Získáme všechny vstupní položky
  const inputs = $input.all();

  // Proměnné pro uložení nalezených dat
  let internalData = null;
  let externalData = null;
  let relationshipsData = null; 
  let analysisType = null;
  let company = "";

  // Nejprve získáme typ analýzy z parse_user_query, pokud je k dispozici
  const userQuery = $('parse_user_query').first()?.json;
  if (userQuery && userQuery.analysis_type) {
    analysisType = userQuery.analysis_type;
  }

  // Projdeme všechny vstupy a identifikujeme je podle struktury
  inputs.forEach(input => {
    const data = input.json;

    // Extrakce jména společnosti - bere první nenulovou hodnotu
    if (data.company && data.company !== "") {
      company = data.company;
    }

    // Identifikace interních dat
    if (data.company_profile || data.tool === "tool_parse_internal_data") {
      internalData = data.company_profile || {};
    }

    // Identifikace externích dat
    if (data.external_data || data.tool === "tool_parse_external_data") {
      externalData = data;

      // Typ analýzy bereme z externalData pouze pokud ještě není nastaven
      if (!analysisType && data.analysis_type) {
        analysisType = data.analysis_type;
      }
    }

    // OPRAVENO: Identifikace vztahových dat podle správných properties
    if (data.relationship_analysis || data.tool === "tool_parse_relationships" || 
        data.relationships || data.visualization_data) {
      relationshipsData = data;
    }
  });

  // Nastavení výchozího typu analýzy, pokud nebyl nalezen
  if (!analysisType) {
    analysisType = "risk_comparison";
  }

  // Sestavení výsledného objektu s typem analýzy a všemi potřebnými daty
  return {
    json: {
      company: company,
      companies: [company], // Pro budoucí rozšíření na více společností
      analysis_type: analysisType,
      external_data: externalData?.external_data || {},
      risk_analysis: externalData?.risk_analysis || {},
      internal_data: internalData || {},
      // OPRAVENO: Správné předání struktury pro relationships
      relationships: {
        // Explicitně nastavujeme has_relationships na true, pokud máme data
        has_relationships: !!relationshipsData,
        // Prioritní použití správných properties
        data: relationshipsData?.relationship_analysis || 
              relationshipsData?.relationships?.data || 
              {},
        // Správné předání vizualizačních dat
        visualization: relationshipsData?.visualization_data || 
                       relationshipsData?.relationships?.visualization || 
                       {nodes: [], links: []}
      }
    }
  };
} catch (error) {
  // V případě chyby vrátíme všechny vstupy nezměněné
  return $input.all();
}

// Získání typu analýzy z Code1
const analysisType = $('prepare_external_data').first().json.analysis_type || "risk_comparison";

return {
  json: {
    has_relationships: false,
    analysis_type: analysisType,  // Předání typu analýzy
    relationships: [],
    visualization: {
      nodes: [],
      links: []
    }
  }
};

// generate_supervisor_prompt - zajištění správné volby nástrojů podle typu analýzy
try {
  // Získáme údaje o analýze a společnostech
  const data = $input.first().json;
  const analysisType = data.analysis_type || "general";

  // Extrakce jména společnosti
  const company = data.company || "";
  const companyText = company ? `company ${company}` : "specified company";

  // Vytvoření základního promptu pro Supervisora
  let supervisorPrompt = `You are a company analysis assistant specialized in risk assessment and supplier analysis.

You have access to the following tools:

- analyze_external_risks: Analyze external risk factors and compliance data for the company.
- analyze_internal_data: Analyze internal company data including tier classification, HS codes, and business activities.
- analyze_relationships: Analyze relationships between entities, identifying business networks and supply chains.

`;

  // Přizpůsobení promptu podle typu analýzy
  if (analysisType === "risk_comparison") {
    supervisorPrompt += `You are analyzing risk factors for ${companyText}.

Based on the analysis type (risk_comparison), use analyze_external_risks and analyze_internal_data to provide a comprehensive risk assessment and compliance analysis. Include analysis of HS codes and their regulatory implications.`;
  } else if (analysisType === "common_suppliers") {
    supervisorPrompt += `You are analyzing supplier relationships for ${companyText}.

Based on the analysis type (common_suppliers), use analyze_relationships to identify key suppliers, supply chain connections, and any related risks. You should also use analyze_internal_data to understand the company's business activities and product categories.`;
  } else {
    supervisorPrompt += `You are performing a general analysis of ${companyText}.

Based on the available data, use any combination of tools to provide the most relevant and comprehensive analysis, including risk factors, internal company data, and business relationships.`;
  }

  supervisorPrompt += `

Present your findings in a clear, structured format with appropriate headings and bullet points where relevant. Include summary insights at the beginning of your response.`;

  // Vrátíme prompt jako výstup
  return {
    json: {
      generatedPrompt: supervisorPrompt
    }
  };
} catch (error) {
  // V případě chyby vrátíme základní prompt
  return {
    json: {
      generatedPrompt: "You are a company analysis assistant. Please analyze the provided company data."
    }
  };
}

// analyze_external_risks
try {
  // První pokus získat data z inputData (explicitně předaná)
  const inputData = $input.first().json || {};

  // Druhý pokus - získat data z rootScope (globální kontext)
  const rootData = $('combine_data_objects').first().json || {};

  // Kombinace dat
  const company = inputData.company || rootData.company || "Unknown Company";

  // Přidání diagnostických informací
  console.log("Input data:", JSON.stringify(inputData));
  console.log("Root data:", JSON.stringify(rootData));
  console.log("Using company name:", company);

  // Extract risk data
  const externalData = rootData.external_data || inputData.external_data || {};
  const riskAnalysis = rootData.risk_analysis || {};

  // Create a formatted analysis as a string
  const formattedAnalysis = `
## External Risk Analysis for ${company}

### Sanctions Status
${riskAnalysis.sanctions_status || "No sanctions information available"}

### PEP Connections
${Array.isArray(riskAnalysis.pep_connections) && riskAnalysis.pep_connections.length > 0 
  ? riskAnalysis.pep_connections.join(", ") 
  : "No PEP connections identified"}

### Risk Score
${riskAnalysis.risk_score || "0"}/100

### Risk Factors
${Array.isArray(riskAnalysis.risk_factors) && riskAnalysis.risk_factors.length > 0 
  ? riskAnalysis.risk_factors.join(", ") 
  : "No specific risk factors identified"}
`;

  // Přímý návrat textu pro AI Tool
  return formattedAnalysis;
} catch (error) {
  console.log("Error in analyze_external_risks:", error);
  return "Error occurred during external risk analysis: " + error.message;
}

// analyze_relationships
try {
  // První pokus získat data z inputData (explicitně předaná)
  const inputData = $input.first().json || {};

  // Druhý pokus - získat data z rootScope (globální kontext)
  const rootData = $('combine_data_objects').first().json || {};

  // Kombinace dat
  const company = inputData.company || rootData.company || "Unknown Company";

  // Přidání diagnostických informací
  console.log("Input data:", JSON.stringify(inputData));
  console.log("Root data:", JSON.stringify(rootData));
  console.log("Using company name:", company);

  // Extract relationship data
  const relationships = rootData.relationships || inputData.relationships || {};
  const relationshipData = relationships.data || {};

  // Vytvoření vzorových dat pro ukázku, když data chybí
  const suppliers = Array.isArray(relationshipData.suppliers) 
    ? relationshipData.suppliers 
    : ["Supplier A", "Supplier B", "Supplier C"];

  const customers = Array.isArray(relationshipData.customers) 
    ? relationshipData.customers 
    : ["Customer X", "Customer Y"];

  const ownership = Array.isArray(relationshipData.ownership) 
    ? relationshipData.ownership 
    : [];

  const keyRelationships = Array.isArray(relationshipData.key_relationships) 
    ? relationshipData.key_relationships 
    : [];

  // Create a formatted analysis as a string
  const formattedAnalysis = `
## Relationship Analysis for ${company}

### Key Suppliers
${Array.isArray(suppliers) && suppliers.length > 0 
  ? suppliers.join(", ") 
  : "No suppliers identified"}

### Key Customers
${Array.isArray(customers) && customers.length > 0 
  ? customers.join(", ") 
  : "No customers identified"}

${ownership.length > 0 ? `
### Ownership Structure
${ownership.join(", ")}
` : ''}

${keyRelationships.length > 0 ? `
### Key Business Relationships
${keyRelationships.join(", ")}
` : ''}

### Summary
${company} has ${suppliers.length} key suppliers and ${customers.length} major customers.
`;

  // Přímý návrat textu pro AI Tool
  return formattedAnalysis;
} catch (error) {
  console.log("Error in analyze_relationships:", error);
  return "Error occurred during relationship analysis: " + error.message;
}

// prepare_external_data
const inputData = $input.first().json;

// Správná extrakce názvu společnosti z dat Sayari API
const company = inputData.data?.label || inputData.company_name || inputData.companies?.[0] || "";

// Vytvoření externí_data se správnou strukturou
const external_data = {
  has_results: !!inputData.data,
  // Inicializace entities s daty ze správného místa
  entities: inputData.data ? [
    {
      id: inputData.data.id,
      name: inputData.data.label || company,
      type: inputData.data.type || "Company",
      risk_score: "0"  // V ukázkových datech není risk score
    }
  ] : []
};

// Zpracování externích rizikových dat
return {
  json: {
    tool: "tool_parse_external_data",
    company: company,  // Předání správně extrahovaného názvu společnosti
    analysis_type: inputData.analysis_type || "risk_comparison",
    external_data: external_data,
    risk_analysis: {
      sanctions_status: "Žádné aktivní sankce nenalezeny",
      pep_connections: [],
      compliance_issues: [],
      risk_score: "0",
      risk_factors: inputData.data?.risk_factors ? Object.keys(inputData.data.risk_factors) : []
    },
    risk_summary: `Analýza rizikových faktorů pro společnost ${company} ukazuje celkové skóre rizika 0/100.`
  }
};

// tool_parse_internal_data
const inputData = $input.first().json;

// Extrakce jména společnosti ze supplier_info (opraveno)
const company = inputData.supplier_info?.supplier_name || inputData.companies?.[0] || "";

// Extrakce dat ze supplier_info
let tier_classification = "Neurčeno";
let hs_codes = [];
let business_activities = [];

if (inputData.supplier_info) {
  // Získání tier klasifikace
  tier_classification = inputData.supplier_info.primary_tier || "Neurčeno";

  // Extrakce HS kódů
  hs_codes = inputData.supplier_info.hs_code_matches?.map(match => match.hsCode) || [];

  // Extrakce obchodních aktivit
  business_activities = inputData.supplier_info.identified_activities?.map(activity => activity.activity) || [];
}

// Zpracování interních dat
return {
  json: {
    tool: "tool_parse_internal_data",
    company: company,  // Přenos správného jména společnosti
    company_profile: {
      tier_classification: tier_classification,
      hs_codes: hs_codes,
      business_activities: business_activities,
      geographic_presence: []
    },
    profile_summary: `Společnost ${company} je klasifikována jako ${tier_classification} dodavatel s ${business_activities.length} identifikovanými obchodními aktivitami.`
  }
};

// tool_parse_relationships - pro Sayari API data
  const companies = $input.first().json.companies || [];
  const mainCompany = companies[0] || "Unknown Company";

  // Získání dat z různých možných struktur
  const inputData = $input.first().json;

  // Extrakce vztahů z různých možných struktur
  let relationshipsList = [];

  // Pokud máme strukturu s data.relationships
  if (inputData.data && Array.isArray(inputData.data.relationships)) {
    relationshipsList = inputData.data.relationships;
  }
  // Pokud máme strukturu s relationships polem přímo
  else if (Array.isArray(inputData.relationships)) {
    relationshipsList = inputData.relationships;
  }
  // Pokud máme strukturu, kterou jste právě sdílel
  else if (typeof inputData.relationships === 'object' && Array.isArray(inputData.relationships)) {
    relationshipsList = inputData.relationships;
  }
  // Pokud máme jednoduchou strukturu s relationships atributem
  else if (typeof inputData.total === 'number' && Array.isArray(inputData.relationships)) {
    relationshipsList = inputData.relationships;
  }

  // Pomocné funkce pro generování ID a mapování typů
  function generateNodeId(entityId, fallback) {
    return entityId || `node_${fallback.replace(/\s+/g, '_').toLowerCase()}`;
  }

  function mapRelationshipTypeToColor(type) {
    const typeMap = {
      'has_subsidiary': '#3366CC',
      'subsidiary_of': '#3366CC',
      'has_officer': '#33AA33',
      'officer_of': '#33AA33',
      'has_shareholder': '#CC6633',
      'shareholder_of': '#CC6633',
      'has_supplier': '#9900CC',
      'supplies_to': '#9900CC',
      'supplies': '#9900CC'
    };
    return typeMap[type] || '#AAAAAA';
  }

  function mapEntityTypeToShape(type) {
    const typeMap = {
      'company': 'circle',
      'person': 'triangleUp',
      'organization': 'square'
    };
    return typeMap[type] || 'circle';
  }

  // Inicializace uzlů a hran
  const nodes = new Map();
  const links = [];

  // Přidání hlavního uzlu (analyzovaná společnost)
  const mainNodeId = generateNodeId('main_entity', mainCompany);
  nodes.set(mainNodeId, {
    id: mainNodeId,
    label: mainCompany,
    data: {
      type: 'company',
      isMain: true,
      shape: 'circle',
      color: '#FF6600'  // Výrazná barva pro hlavní entitu
    }
  });

  // Zpracování vztahů ze získaného seznamu
  if (relationshipsList.length > 0) {
    relationshipsList.forEach((relationship) => {
      const sourceId = relationship.source?.id || relationship.from_id || generateNodeId(null, relationship.source?.label ||
  relationship.from_label || 'source');
      const targetId = relationship.target?.id || relationship.to_id || generateNodeId(null, relationship.target?.label ||
  relationship.to_label || 'target');
      const sourceLabel = relationship.source?.label || relationship.from_label || 'Unknown Source';
      const targetLabel = relationship.target?.label || relationship.to_label || 'Unknown Target';
      const sourceType = relationship.source?.type || relationship.from_type || 'company';
      const targetType = relationship.target?.type || relationship.to_type || 'company';
      const relationType = relationship.type;

      // Přidání zdrojového uzlu, pokud ještě neexistuje
      if (!nodes.has(sourceId)) {
        nodes.set(sourceId, {
          id: sourceId,
          label: sourceLabel,
          data: {
            type: sourceType,
            isMain: sourceId === mainNodeId,
            shape: mapEntityTypeToShape(sourceType),
            color: '#5599FF'
          }
        });
      }

      // Přidání cílového uzlu, pokud ještě neexistuje
      if (!nodes.has(targetId)) {
        nodes.set(targetId, {
          id: targetId,
          label: targetLabel,
          data: {
            type: targetType,
            isMain: targetId === mainNodeId,
            shape: mapEntityTypeToShape(targetType),
            color: '#5599FF'
          }
        });
      }

      // Přidání hrany mezi uzly
      links.push({
        id: relationship.id || `edge_${sourceId}_${targetId}`,
        source: sourceId,
        target: targetId,
        label: relationType,
        data: {
          type: relationType,
          color: mapRelationshipTypeToColor(relationType),
          // Extrakce metadat z různých možných míst
          metadata: relationship.metadata || relationship.attributes || {}
        }
      });
    });
  }
  // Alternativní zpracování dat ze struktury s dodavateli, zákazníky, atd.
  else if (inputData.suppliers || inputData.customers || inputData.data?.suppliers || inputData.data?.customers) {
    // Získání seznamů dodavatelů a zákazníků z možných míst
    const suppliers = inputData.suppliers || inputData.data?.suppliers || [];
    const customers = inputData.customers || inputData.data?.customers || [];

    // Zpracování dodavatelů
    suppliers.forEach((supplier, index) => {
      const supplierId = generateNodeId(null, `supplier_${index}`);
      const supplierName = typeof supplier === 'string' ? supplier : supplier.name || `Supplier ${index + 1}`;

      nodes.set(supplierId, {
        id: supplierId,
        label: supplierName,
        data: {
          type: 'company',
          subType: 'supplier',
          shape: 'circle',
          color: '#3366CC'
        }
      });

      links.push({
        id: `edge_${supplierId}_${mainNodeId}`,
        source: supplierId,
        target: mainNodeId, // Dodavatel -> Společnost
        label: 'supplies',
        data: {
          type: 'supplies',
          color: '#3366CC'
        }
      });
    });

    // Zpracování zákazníků
    customers.forEach((customer, index) => {
      const customerId = generateNodeId(null, `customer_${index}`);
      const customerName = typeof customer === 'string' ? customer : customer.name || `Customer ${index + 1}`;

      nodes.set(customerId, {
        id: customerId,
        label: customerName,
        data: {
          type: 'company',
          subType: 'customer',
          shape: 'circle',
          color: '#CC3366'
        }
      });

      links.push({
        id: `edge_${mainNodeId}_${customerId}`,
        source: mainNodeId,
        target: customerId, // Společnost -> Zákazník
        label: 'supplies to',
        data: {
          type: 'supplies_to',
          color: '#CC3366'
        }
      });
    });
  }

  // Pokud nemáme žádné vztahy, vytvoříme alespoň vzorová data pro testování
  if (links.length === 0) {
    const sampleRelations = [
      { id: 'supplier_1', label: 'Sample Supplier A', type: 'supplier', relationship: 'supplies' },
      { id: 'supplier_2', label: 'Sample Supplier B', type: 'supplier', relationship: 'supplies' },
      { id: 'customer_1', label: 'Sample Customer X', type: 'customer', relationship: 'supplies_to' },
      { id: 'owner_1', label: 'Sample Owner Corp', type: 'owner', relationship: 'owns' }
    ];

    sampleRelations.forEach(entity => {
      const entityId = generateNodeId(entity.id, entity.label);

      // Přidání uzlu
      nodes.set(entityId, {
        id: entityId,
        label: entity.label,
        data: {
          type: 'company',
          subType: entity.type,
          shape: 'circle',
          color: entity.type === 'supplier' ? '#3366CC' :
                 entity.type === 'customer' ? '#CC3366' : '#CCAA33'
        }
      });

      // Přidání hrany
      const isInbound = entity.type === 'supplier' || entity.type === 'owner';
      links.push({
        id: `edge_${isInbound ? entityId : mainNodeId}_${isInbound ? mainNodeId : entityId}`,
        source: isInbound ? entityId : mainNodeId,
        target: isInbound ? mainNodeId : entityId,
        label: entity.relationship,
        data: {
          type: entity.relationship,
          color: entity.type === 'supplier' ? '#3366CC' :
                 entity.type === 'customer' ? '#CC3366' : '#CCAA33'
        }
      });
    });
  }

  // Převod Map na pole pro výstup
  const nodesArray = Array.from(nodes.values());

  // Debug informace pro ladění
  console.log("Input data structure:", JSON.stringify(inputData, null, 2).substring(0, 500));
  console.log("Extracted relationships:", relationshipsList.length);
  console.log("Generated nodes:", nodesArray.length);
  console.log("Generated links:", links.length);

  // Výsledná struktura pro Trellis
  return {
    json: {
      tool: "tool_parse_relationships",
      companies: companies,
      relationship_analysis: {
        suppliers: inputData.suppliers || inputData.data?.suppliers || [],
        customers: inputData.customers || inputData.data?.customers || [],
        ownership: inputData.ownership || inputData.data?.ownership || [],
        key_relationships: inputData.key_relationships || inputData.data?.key_relationships || []
      },
      visualization_data: {
        nodes: nodesArray,
        links: links
      },
      relationship_summary: `Analýza vztahů pro společnost ${mainCompany} identifikovala ${nodesArray.length - 1} souvisejících 
  entit a ${links.length} vztahů.`
    }
  };

// analyze_internal_data - správný přístup k datům
try {
  // Kontrola přímého vstupu z Supervisora
  const directInput = $input.first().json || {};
  console.log("Přímý vstup do analyze_internal_data:", JSON.stringify(directInput));

  // Přístup k datům z jiných míst ve workflow
  const internalInput = $('prepare_internal_data').first()?.json;
  const combinedInput = $('combine_data_objects').first()?.json;

  console.log("prepare_internal_data výstup:", JSON.stringify(internalInput));
  console.log("combine_data_objects výstup:", JSON.stringify(combinedInput));

  // Pokus o nalezení dat v různých místech
  const company = directInput.company || combinedInput?.company || "Unknown Company";

  // KLÍČOVÁ ČÁST: Prioritní přístup k datům z prepare_internal_data
  const companyProfile = internalInput?.company_profile || 
                        combinedInput?.internal_data || 
                        directInput.internal_data || {};

  // Formátování výstupu
  return `
## Internal Data Analysis for ${company}

### Tier Classification
${companyProfile.tier_classification || "Tier classification not available"}

### HS Codes
${Array.isArray(companyProfile.hs_codes) && companyProfile.hs_codes.length > 0 
  ? companyProfile.hs_codes.map(code => `- ${code}`).join("\n") 
  : "No HS codes identified"}

### Business Activities
${Array.isArray(companyProfile.business_activities) && companyProfile.business_activities.length > 0 
  ? companyProfile.business_activities.map(activity => `- ${activity}`).join("\n") 
  : "No business activities identified"}

### Geographic Presence
${Array.isArray(companyProfile.geographic_presence) && companyProfile.geographic_presence.length > 0 
  ? companyProfile.geographic_presence.join(", ") 
  : "Geographic presence data not available"}

### Summary
${company} is classified as a ${companyProfile.tier_classification || "unknown tier"} supplier with ${Array.isArray(companyProfile.business_activities) ? companyProfile.business_activities.length : 0} identified business activities and ${Array.isArray(companyProfile.hs_codes) ? companyProfile.hs_codes.length : 0} HS codes.
`;
} catch (error) {
  console.log("Error in analyze_internal_data:", error);
  return "Error occurred during internal data analysis: " + error.message;
}

